export function stepMatches(step,values){const actual=values[step[2]],target=step[3];return typeof target==='number'?Number.isFinite(Number(actual))&&Math.abs(Number(actual)-target)<=Math.max(1e-8,Math.abs(target)*.001):actual===target;}
